<template><div class="shell"><header class="topbar"><button class="back" @click="router.back()">‹</button><strong>库存概览</strong><span></span></header><main class="content page"><div class="kpi-grid"><Kpi label="库存总金额" :value="`¥${money(totalAmount)}`"/><Kpi label="库存件数" :value="totalQty"/></div><Panel title="库存预警"><div v-for="w in warnings" :key="w.goods_id" class="list-card"><span>{{ w.goods_name||w.name }}</span><strong class="error">剩余 {{ w.stock }}</strong></div><div v-if="!warnings.length" class="empty">库存充足</div></Panel><Panel title="旧料/板料库存"><div v-for="m in oldMaterials" :key="m.material_type" class="rank-row"><span>{{ m.material_type }}</span><strong>{{ Number(m.total_weight||0) }}g</strong><small>¥{{ money(m.total_value) }} · {{ m.inbound_count||0 }}笔</small></div><div v-if="!oldMaterials.length" class="empty">暂无旧料</div></Panel></main></div></template><script setup>import{computed,onMounted,ref,watch}from'vue';import{useRouter}from'vue-router';import{api}from'../api/request.js';import{useAppStore}from'../stores/app.js';import Kpi from'../components/Kpi.vue';import Panel from'../components/Panel.vue';const router=useRouter(),app=useAppStore(),roots=ref([]),warnings=ref([]),oldMaterials=ref([]),money=v=>Number(v||0).toFixed(2);const totalAmount=computed(()=>roots.value.reduce((s,r)=>s+Number(r.amount||0),0));const totalQty=computed(()=>roots.value.reduce((s,r)=>s+Number(r.quantity||0),0));async function load(){const s=await api.stock()||[];roots.value=Array.isArray(s)?s:[];warnings.value=await api.warnings()||[];try{oldMaterials.value=await api.oldMaterial()||[]}catch{oldMaterials.value=[]}}onMounted(load);watch(()=>app.eventVersion,()=>{if(['STOCK_UPDATED','STOCK_IN_COMPLETED','OLD_MATERIAL_UPDATED','APPROVAL_DECIDED'].includes(app.lastEventType))load()})</script>
